util.AddNetworkString("ZPhoneAction")
util.AddNetworkString("ZPhoneSync")
util.AddNetworkString("ZPhoneEvent")

ZPHONE.MaxAccountsPerPlayer = 300
ZPHONE.SavePath = "zphone_store.json"
ZPHONE.Handlers = ZPHONE.Handlers or {}

-- account numbers are the keys of Store.accounts, so they're generated by newNumber() below, not counted up
ZPHONE.Store = ZPHONE.Store or { accounts = {}, groups = {}, nextGroup = 1, msgSeq = 0 }
local Store = ZPHONE.Store

-- false while the store file is busted. then nothing gets written over it, see writeStore
local storeOk = false

local function sid(ply)
	return ply:SteamID64()
end

local function cleanText(s, maxLen)
	s = string.Trim(tostring(s or ""))
	if utf8.len(s) and utf8.len(s) > maxLen then
		s = string.sub(s, 1, maxLen)
	end
	return s
end
ZPHONE.CleanText = cleanText

local function ensureAcc(acc)
	acc.contacts = acc.contacts or {}
	acc.messages = acc.messages or {}
	acc.blocked = acc.blocked or {}
	acc.notes = acc.notes or ""
	return acc
end

local function accountsOf(ply)
	local list = {}
	for _, acc in pairs(Store.accounts) do
		if acc.owner == sid(ply) then list[#list + 1] = acc end
	end
	table.sort(list, function(a, b) return tonumber(a.number) < tonumber(b.number) end)
	return list
end
ZPHONE.AccountsOf = accountsOf

Store.bound = Store.bound or {}

function ZPHONE.CharOf(ply)
	return Store.bound[sid(ply)] or ""
end

function ZPHONE.AccountsOfChar(ply, char)
	local owner, list = sid(ply), {}
	for _, acc in pairs(Store.accounts) do
		if acc.owner == owner and (acc.char or "") == char then list[#list + 1] = acc end
	end
	table.sort(list, function(a, b) return tonumber(a.number) < tonumber(b.number) end)
	return list
end

-- a new account number: a real NYC area code, then a random exchange and line. never one that's already on an account.
-- exchanges can't be 555 (the TV-movie number) or end in 11 (211, 311 ... 911 are service codes, not numbers you can get)
local function newNumber()
	local areas = ZPHONE.Config.NYCAreaCodes
	for _ = 1, 500 do
		local exch = math.random(200, 999)
		if exch ~= 555 and exch % 100 ~= 11 then
			local num = areas[math.random(#areas)] .. tostring(exch) .. string.format("%04d", math.random(0, 9999))
			if not Store.accounts[num] then return num end
		end
	end
end

function ZPHONE.CreateAccount(ply, char, name)
	if #accountsOf(ply) >= ZPHONE.MaxAccountsPerPlayer then
		return nil, "you already have enough numbers. this isn't a cult."
	end
	name = cleanText(name, 24)
	if name == "" then return nil, "pick a name first" end

	local num = newNumber()
	if not num then return nil, "couldn't get a free number, try again" end

	local acc = ensureAcc({ number = num, name = name, owner = sid(ply), char = char or "" })
	Store.accounts[num] = acc
	ZPHONE.Save()
	return acc
end

local function activeOf(ply)
	local char = ZPHONE.CharOf(ply)
	local list = ZPHONE.AccountsOfChar(ply, char)
	if #list == 0 then
		local acc = ZPHONE.CreateAccount(ply, char, char ~= "" and char or ply:Nick())
		if not acc then return nil end
		list = { acc }
	end
	local pick
	for _, a in ipairs(list) do
		if a.inUse then pick = a break end
	end
	if not pick then
		pick = list[1]
		pick.inUse = true
		ZPHONE.Save()
	end
	return pick
end
ZPHONE.ActiveOf = activeOf

function ZPHONE.SetInUse(ply, char, num)
	local owner = sid(ply)
	for _, acc in pairs(Store.accounts) do
		if acc.owner == owner and (acc.char or "") == char then
			acc.inUse = (acc.number == num) or nil
		end
	end
	ZPHONE.Save()
end

function ZPHONE.BindChar(ply, char)
	Store.bound[sid(ply)] = (char ~= "") and char or nil
	ZPHONE.Save()
end

function ZPHONE.OwnedAccount(ply, num)
	local acc = Store.accounts[tostring(num)]
	if acc and acc.owner == sid(ply) then return acc end
end

function ZPHONE.DeleteAccount(ply, char, num)
	local acc = ZPHONE.OwnedAccount(ply, num)
	if not acc or (acc.char or "") ~= char then return "that number isn't on this character" end
	if ZPHONE.CallOf[acc.number] then return "that line is on a call. hang up first" end

	local list = ZPHONE.AccountsOfChar(ply, char)
	if #list <= 1 then return "a character needs at least one number" end

	Store.accounts[acc.number] = nil
	if acc.inUse then
		for _, other in ipairs(list) do
			if other ~= acc then other.inUse = true break end
		end
	end
	ZPHONE.Save()
	return nil
end

function ZPHONE.PlayerForNumber(num)
	local acc = Store.accounts[tostring(num)]
	if not acc then return end
	for _, p in ipairs(player.GetAll()) do
		if p:SteamID64() == acc.owner then return p end
	end
end

function ZPHONE.PushMessage(acc, msg)
	acc.messages[#acc.messages + 1] = msg
	while #acc.messages > ZPHONE.Config.MaxMessagesPerAccount do
		table.remove(acc.messages, 1)
	end
end

local function nextMsgId()
	Store.msgSeq = (Store.msgSeq or 0) + 1
	return Store.msgSeq
end

ZPHONE.NOSYNC = {}

-- the file write. the store is only written when it loaded fine (or there was no file yet), so a busted file isn't overwritten
local function writeStore()
	if not storeOk then return end
	file.Write(ZPHONE.SavePath, util.TableToJSON(Store, false))
end

-- saves wait a few seconds so a burst of changes is one write
local function save()
	timer.Create("ZPhoneSave", 3, 1, writeStore)
end
ZPHONE.Save = save

-- the wait above means a restart right after a change would lose it. write now when the server shuts down
hook.Add("ShutDown", "ZPhone_SaveOnShutdown", function()
	timer.Remove("ZPhoneSave")
	writeStore()
end)

local function load()
	local raw = file.Read(ZPHONE.SavePath, "DATA")
	if not raw then
		storeOk = true -- first run, nothing saved yet
		return
	end

	-- util.JSONToTable(json, ignoreLimits, ignoreConversions). the third one matters: by default it turns numeric-looking
	-- keys into numbers, so Store.accounts["1000001"] and Store.bound[steamid] stop matching after a restart.
	-- the file itself always has string keys, so this reads the saved accounts back the way they were written
	local t = util.JSONToTable(raw, false, true)
	if not t then
		MsgC(Color(255, 100, 100), "[zphone] store file is busted, not overwriting it. go look at data/" .. ZPHONE.SavePath .. "\n")
		return
	end
	storeOk = true

	Store.accounts = t.accounts or {}
	Store.feed = t.feed or {}
	Store.feedNext = t.feedNext or 1
	Store.feedPeople = t.feedPeople or {}
	Store.groups = t.groups or {}
	Store.nextGroup = t.nextGroup or 1
	Store.msgSeq = t.msgSeq or 0
	Store.bound = t.bound or {}
	Store.power = t.power or {}
	for _, acc in pairs(Store.accounts) do ensureAcc(acc) end
end
load()

function ZPHONE.Event(ply, kind, data)
	if not IsValid(ply) then return end
	net.Start("ZPhoneEvent")
		net.WriteString(kind)
		net.WriteTable(data or {})
	net.Send(ply)
end

function ZPHONE.BuildSync(ply)
	local accs = accountsOf(ply)
	local active = activeOf(ply)

	local data = {
		accounts = {},
		active = active and active.number or nil,
		char = ZPHONE.CharOf(ply),
		maxAccounts = ZPHONE.MaxAccountsPerPlayer,
		messages = {},
		contacts = {},
		blocked = {},
		-- group chats this number is in, keyed by group id
		groups = {},
		notes = "",
		-- the fake spam senders, number -> name. same for everyone
		spamNames = ZPHONE.Config.Spam.senders,
		-- the city alerts sender. not in spamNames, so it sits in the inbox, and the client makes it no-reply
		alertNumber = ZPHONE.Config.Alerts.number,
		alertName = ZPHONE.Config.Alerts.name,
		-- the newest posts on the social feed, with likes counted for this player
		feed = ZPHONE.FeedFor(active),
		-- battery and the crack. the client draws both in the status bar and the settings app
		power = ZPHONE.PowerData(ply),
		mapPoints = ZPHONE.MapPointsForSync(),
	}

	for _, a in ipairs(accs) do
		data.accounts[#data.accounts + 1] = { number = a.number, name = a.name }
	end

	if active then
		data.contacts = active.contacts
		data.blocked = active.blocked
		data.notes = active.notes or ""
		for gid, g in pairs(Store.groups) do
			if table.HasValue(g.members, active.number) then data.groups[gid] = g end
		end
		local m = active.messages
		for i = math.max(1, #m - 119), #m do
			data.messages[#data.messages + 1] = m[i]
		end
	end

	if ZPHONE.CallStateFor then
		data.call = ZPHONE.CallStateFor(ply)
	end

	return data
end

function ZPHONE.Sync(ply)
	if not IsValid(ply) then return end
	net.Start("ZPhoneSync")
		net.WriteTable(ZPHONE.BuildSync(ply))
	net.Send(ply)
end

ZPHONE.Handlers.requestsync = function(ply) end

ZPHONE.Handlers.sendmsg = function(ply, d)
	local me = activeOf(ply)
	if not me then return "no active account" end

	local to = tostring(d.to or "")
	local text = cleanText(d.text, ZPHONE.Config.MaxMessageLength)
	if text == "" then return end

	local target = Store.accounts[to]
	if not target then return "number doesn't exist. dead air." end
	if target.number == me.number then return "texting yourself is a cry for help" end
	if target.blocked[me.number] then
		ZPHONE.Event(ply, "sent")
		return
	end

	local now = os.time()
	local id = nextMsgId()
	ZPHONE.PushMessage(me, { id = id, with = to, from = me.number, text = text, t = now, out = true, seen = {} })
	ZPHONE.PushMessage(target, { id = id, with = me.number, from = me.number, text = text, t = now })
	local recv = ZPHONE.PlayerForNumber(to)
	if IsValid(recv) then
		ZPHONE.Event(recv, "buzz")
		ZPHONE.Sync(recv)
	end

	ZPHONE.Event(ply, "sent")
	save()
end

ZPHONE.Handlers.addcontact = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	local num = tostring(d.number or "")
	local other = Store.accounts[num]
	if not other then return "that number is dead" end
	local name = cleanText(d.name, 24)
	if name == "" then name = other.name end
	me.contacts[num] = name
	save()
end

ZPHONE.Handlers.delcontact = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	me.contacts[tostring(d.number or "")] = nil
	save()
end

ZPHONE.Handlers.block = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	local num = tostring(d.number or "")
	if num == me.number then return "you can't block yourself. we see what you're doing." end
	if num == ZPHONE.Config.Alerts.number then return "city alerts can't be blocked. sorry." end
	me.blocked[num] = d.on and true or nil
	save()
end

ZPHONE.Handlers.savenote = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	me.notes = cleanText(d.text, ZPHONE.Config.MaxNotesLength)
	save()
end

ZPHONE.Handlers.read = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	local with = tostring(d.with or "")
	local group = Store.groups[with]
	local now = os.time()
	local changed = false
	local touched = {}

	for _, m in ipairs(me.messages) do
		if m.with == with and m.id and not m.out and not (m.seen and m.seen[me.number]) then
			local holders = { me.number }
			if group then
				for _, num in ipairs(group.members) do holders[#holders + 1] = num end
			else
				holders[#holders + 1] = m.from
			end
			for _, num in ipairs(holders) do
				local acc = Store.accounts[tostring(num)]
				if acc then
					for _, c in ipairs(acc.messages) do
						if c.id == m.id then
							c.seen = c.seen or {}
							c.seen[me.number] = now
						end
					end
					touched[tostring(num)] = true
				end
			end
			changed = true
		end
	end

	for num in pairs(touched) do
		if num ~= me.number then
			local p = ZPHONE.PlayerForNumber(num)
			if IsValid(p) then ZPHONE.Sync(p) end
		end
	end
	if changed then save() end
end

ZPHONE.Handlers.typing = function(ply, d)
	local me = activeOf(ply)
	if not me then return ZPHONE.NOSYNC end
	local to = tostring(d.to or "")
	local group = Store.groups[to]
	local targets = { to }
	if group then
		if not table.HasValue(group.members, me.number) then return ZPHONE.NOSYNC end
		targets = group.members
	end

	for _, num in ipairs(targets) do
		local acc = Store.accounts[tostring(num)]
		if acc and acc.number ~= me.number and not acc.blocked[me.number] then
			local p = ZPHONE.PlayerForNumber(acc.number)
			-- the dots say who's typing: the group's id for a group, your number for a text
			if IsValid(p) then ZPHONE.Event(p, "typing", { with = group and to or me.number, name = me.number }) end
		end
	end
	return ZPHONE.NOSYNC
end

ZPHONE.Handlers.creategroup = function(ply, d)
	local me = activeOf(ply)
	if not me then return "no active account" end
	local C = ZPHONE.Config.Groups

	local picked, taken = {}, { [me.number] = true }
	for _, num in ipairs(istable(d.members) and d.members or {}) do
		num = tostring(num)
		local acc = Store.accounts[num]
		if acc and not taken[num] and not acc.blocked[me.number] and not me.blocked[num] then
			taken[num] = true
			picked[#picked + 1] = num
		end
	end
	if #picked == 0 then return "none of those numbers can join a group" end
	if #picked + 1 > C.maxMembers then return "a group takes " .. C.maxMembers .. " people, tops" end

	local name = cleanText(d.name, C.maxName)
	if name == "" then name = "group" end

	local gid = "G" .. Store.nextGroup
	Store.nextGroup = Store.nextGroup + 1
	local members = { me.number }
	for _, num in ipairs(picked) do members[#members + 1] = num end
	Store.groups[gid] = { id = gid, name = name, members = members, owner = me.number }

	-- a line in the history for everyone in it, then a sync so the group shows up on every phone right away
	local now = os.time()
	local line = (me.name or "someone") .. " made the group"
	for _, num in ipairs(members) do
		ZPHONE.PushMessage(Store.accounts[num], { id = nextMsgId(), with = gid, from = me.number, text = line, t = now, group = true, system = true })
		local p = ZPHONE.PlayerForNumber(num)
		if IsValid(p) and num ~= me.number then
			ZPHONE.Event(p, "buzz", { text = name })
			ZPHONE.Sync(p)
		end
	end
	save()
end

ZPHONE.Handlers.groupsend = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	local gid = tostring(d.to or "")
	local group = Store.groups[gid]
	if not group or not table.HasValue(group.members, me.number) then return "you're not in that group anymore" end

	local text = cleanText(d.text, ZPHONE.Config.MaxMessageLength)
	if text == "" then return end

	local now = os.time()
	local id = nextMsgId()
	for _, num in ipairs(group.members) do
		local acc = Store.accounts[num]
		if acc and num == me.number then
			ZPHONE.PushMessage(acc, { id = id, with = gid, from = me.number, text = text, t = now, out = true, group = true, seen = {} })
		elseif acc and not acc.blocked[me.number] then
			-- a member who blocked you never sees it, same as a text
			ZPHONE.PushMessage(acc, { id = id, with = gid, from = me.number, text = text, t = now, group = true })
			local p = ZPHONE.PlayerForNumber(num)
			if IsValid(p) then
				ZPHONE.Event(p, "buzz", { text = group.name })
				ZPHONE.Sync(p)
			end
		end
	end

	ZPHONE.Event(ply, "sent")
	save()
end

-- leaving takes your copy of the history with you. whoever's left gets a line about it
ZPHONE.Handlers.leavegroup = function(ply, d)
	local me = activeOf(ply)
	if not me then return end
	local gid = tostring(d.id or "")
	local group = Store.groups[gid]
	if not group or not table.HasValue(group.members, me.number) then return end

	table.RemoveByValue(group.members, me.number)
	for i = #me.messages, 1, -1 do
		if me.messages[i].with == gid then table.remove(me.messages, i) end
	end

	if #group.members == 0 then
		Store.groups[gid] = nil
	else
		local now = os.time()
		local line = (me.name or "someone") .. " left"
		for _, num in ipairs(group.members) do
			local acc = Store.accounts[num]
			if acc then
				ZPHONE.PushMessage(acc, { id = nextMsgId(), with = gid, from = me.number, text = line, t = now, group = true, system = true })
			end
			local p = ZPHONE.PlayerForNumber(num)
			if IsValid(p) and num ~= me.number then ZPHONE.Sync(p) end
		end
	end
	save()
end

-- ========== dispatcher ==========

net.Receive("ZPhoneAction", function(len, ply)
	local action = net.ReadString()
	local data = net.ReadTable() or {}

	-- rate limit. the client spams taps, the server says no sometimes
	if (ply.ZPhoneNextAct or 0) > CurTime() then return end
	ply.ZPhoneNextAct = CurTime() + 0.1

	-- a dead battery means the phone does nothing. say so, then stop
	if ZPHONE.Dead(ply) then
		ZPHONE.Event(ply, "error", { text = "battery's dead. ask an admin to charge it" })
		return
	end

	local handler = ZPHONE.Handlers[action]
	if not handler then return end

	local ok, err = pcall(handler, ply, data)
	if not ok then
		ErrorNoHalt("[zphone] handler '" .. tostring(action) .. "' blew up: " .. tostring(err) .. "\n")
		return
	end
	if err == ZPHONE.NOSYNC then return end
	if isstring(err) then
		ZPHONE.Event(ply, "error", { text = err })
	end

	ZPHONE.Sync(ply)
end)

hook.Add("PlayerInitialSpawn", "ZPhone_FirstSync", function(ply)
	ply.ZPhoneActive = nil
end)

-- ========== spam ==========
-- fake senders with no account behind them. they buzz, they land in the spam tab, and there's nobody to reply to

local function deliverSpam(ply, acc)
	local C = ZPHONE.Config.Spam
	local nums = table.GetKeys(C.senders)
	if #nums == 0 or #C.texts == 0 then return end

	local num = nums[math.random(#nums)]
	if acc.blocked[num] then return end

	local text = C.texts[math.random(#C.texts)]
	ZPHONE.PushMessage(acc, { with = num, from = num, text = text, t = os.time() })

	-- the buzz says who it's from, so the banner reads like a real notification
	ZPHONE.Event(ply, "buzz", { text = C.senders[num] })
	ZPHONE.Sync(ply)
	save()
end

local function spamTick()
	if not ZPHONE.Config.Spam.enabled then return end
	for _, ply in ipairs(player.GetAll()) do
		for _, acc in ipairs(accountsOf(ply)) do
			if math.random() < ZPHONE.Config.Spam.chance then
				deliverSpam(ply, acc)
			end
		end
	end
end

timer.Create("ZPhoneSpam", ZPHONE.Config.Spam.rollEvery, 0, spamTick)

-- ========== city alerts ==========
-- zphone_alert "Area" "Text of the alert"
-- free text. anything with spaces needs quotes. it goes to every online player's inbox, from CITY ALERTS.
-- run from the server console, or from the in-game console by an admin. every alert is logged to data/zphone_alerts.log

local ALERT_COOLDOWN = 5
local nextAlert = 0

local function sendAlert(area, text, who)
	local C = ZPHONE.Config.Alerts
	local line = "[" .. area .. "] " .. text
	local reached = 0

	for _, p in ipairs(player.GetAll()) do
		local accs = accountsOf(p)
		for _, acc in ipairs(accs) do
			ZPHONE.PushMessage(acc, { with = C.number, from = C.number, text = line, t = os.time(), alert = true })
		end
		if #accs > 0 then
			reached = reached + 1
			ZPHONE.Event(p, "buzz", { text = C.name })
		end
		ZPHONE.Sync(p)
	end
	save()

	-- the same alert goes on the feed, so it shows up there as an official post too
	ZPHONE.AddFeedPost({ author = C.name, handle = "cityalerts", text = line, kind = "official" })

	file.Append("zphone_alerts.log", string.format("%s  %s  [%s] %s\n", os.date("%Y-%m-%d %H:%M:%S"), who, area, text))
	print("[zphone] alert sent to " .. reached .. " player(s): " .. line)
	return reached
end

concommand.Add("zphone_alert", function(ply, cmd, args)
	local who = IsValid(ply) and ply:Nick() or "console"

	if IsValid(ply) and not ZPHONE.Config.IsAdminForPings(ply) then
		ply:ChatPrint("[zphone] admins only.")
		return
	end

	local area = cleanText(args[1], 24)
	local text = cleanText(table.concat(args, " ", 2), 200)
	if area == "" or text == "" then
		local usage = 'usage: zphone_alert "Area" "Text of the alert"'
		print("[zphone] " .. usage)
		if IsValid(ply) then ply:ChatPrint("[zphone] " .. usage) end
		return
	end

	if CurTime() < nextAlert then
		print("[zphone] wait a few seconds between alerts")
		return
	end
	nextAlert = CurTime() + ALERT_COOLDOWN

	sendAlert(area, text, who)
end)

